{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "The closest retrieved analogue, an m-tolyl urea-anthraquinone, has a measured human oral bioavailability of 78.6%, supporting high F for the similarly substituted m-tolyl urea/sulfonylurea query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Tolbutamide, a prototypical sulfonylurea sharing the sulfonylurea-isopropyl urea pharmacophore, has an absolute oral bioavailability of 0.85 in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tolbutamide is characterized by low clearance and good absolute oral bioavailability in humans, indicating that sulfonylureas are not subject to major first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lumiracoxib, a moderately similar small molecule, shows 74% absolute oral bioavailability in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lisofylline has low oral bioavailability (5.9%) in humans, but its structure and metabolic profile are distant from the sulfonylurea query, so this contradictory evidence carries little weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small sulfonylurea-like molecule; the closest analogue and multiple sulfonylurea/related drugs show high absolute oral bioavailability in humans (64-100%), while low-F examples are structurally distant and explained by extensive first-pass metabolism not expected for this sulfonylurea. Cirrhosis may reduce clearance but is unlikely to drop F below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "No cirrhosis-specific bioavailability data for close analogues.",
    "Morgan similarity scores are low to moderate, limiting quantitative transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

